cat << 'SCRIPT' > analyze.cs
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild("build.binlog");
var errors = build.FindChildrenRecursive<Error>();
var warnings = build.FindChildrenRecursive<Warning>();

Console.WriteLine("=== BUILD ERRORS ===");
Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine();

foreach (var e in errors)
{
    var project = "";
    var node = e.Parent;
    while (node != null)
    {
        if (node is Project p) { project = p.ProjectFile; break; }
        if (node is Microsoft.Build.Logging.StructuredLogger.Target t) { }
        node = node.Parent as BaseNode;
    }
    Console.WriteLine($"Project: {project}");
    Console.WriteLine($"File: {e.File}");
    Console.WriteLine($"Line: {e.LineNumber}");
    Console.WriteLine($"Code: {e.Code}");
    Console.WriteLine($"Message: {e.Text}");
    Console.WriteLine("---");
}

Console.WriteLine();
Console.WriteLine("=== PROJECT RESULTS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    var succeeded = p.FindChildrenRecursive<Error>().Count == 0;
    if (!succeeded)
        Console.WriteLine($"FAILED: {p.ProjectFile} ({p.FindChildrenRecursive<Error>().Count} errors)");
}
