using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Find all projects and their build status
var projects = build.FindChildrenRecursive<Project>();
Console.WriteLine("=== ALL PROJECTS IN BUILD ===");
foreach (var p in projects.GroupBy(x => x.ProjectFile))
{
    var errs = p.SelectMany(x => x.FindChildrenRecursive<Error>()).Count();
    Console.WriteLine($"  {p.Key} - errors: {errs}");
}

// Look for dependency/reference info
Console.WriteLine("\n=== MESSAGES MENTIONING DEPENDENCIES ===");
var msgs = build.FindChildrenRecursive<Message>()
    .Where(m => m.Text != null && (m.Text.Contains("Newtonsoft") || m.Text.Contains("ProjectReference") || m.Text.Contains("PackageReference")))
    .Take(20);
foreach (var m in msgs)
    Console.WriteLine($"  {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
