using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild(args[0]);
var projects = build.FindChildrenRecursive<Project>();

// Deduplicate by project file, pick ones with errors if any
var grouped = projects.GroupBy(p => p.ProjectFile);
foreach (var g in grouped.Where(x => !x.Key.Contains(".sln")))
{
    Console.WriteLine($"\n=== {g.Key} ===");
    // Collect all references across all evaluations
    var refs = new HashSet<string>();
    foreach (var proj in g)
    {
        var allItems = proj.FindChildrenRecursive<AddItem>();
        foreach (var a in allItems.Where(x => x.Name.Contains("Reference")))
            foreach (var child in a.Children.OfType<Item>())
                refs.Add($"{a.Name}: {child.Name}");
    }
    foreach (var r in refs.OrderBy(x => x))
        Console.WriteLine($"  {r}");

    var totalErrors = g.Sum(p => p.FindChildrenRecursive<Error>().Count);
    Console.WriteLine($"  Total Errors: {totalErrors}");
}
