using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Search all messages for restore/package info about the Services project
var messages = build.FindChildrenRecursive<Message>()
    .Where(m => m.Text != null && m.Text.Contains("Services") && 
           (m.Text.Contains("Package") || m.Text.Contains("package") || m.Text.Contains("Restore")))
    .Take(30);

Console.WriteLine("=== SERVICES-RELATED PACKAGE MESSAGES ===");
foreach (var m in messages)
    Console.WriteLine($"  {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");

// Look for the project file content in evaluation
Console.WriteLine("\n=== LOOKING FOR PROPERTY: PackageReference in Services ===");
var projects = build.FindChildrenRecursive<Project>();
var svcProjects = projects.Where(p => p.ProjectFile?.Contains("Services") == true && !p.ProjectFile.Contains(".sln"));
foreach (var proj in svcProjects.Take(1))
{
    // Check Properties
    var props = proj.FindChildrenRecursive<Property>()
        .Where(p => p.Name != null && (p.Name.Contains("Package") || p.Name.Contains("Reference") || p.Name.Contains("Newtonsoft")));
    foreach (var p in props.Take(20))
        Console.WriteLine($"  Property: {p.Name} = {p.Value?.Substring(0, Math.Min(100, p.Value?.Length ?? 0))}");

    // Check for evaluation folder
    var folders = proj.FindChildrenRecursive<Folder>();
    foreach (var f in folders.Where(x => x.Name?.Contains("Item") == true).Take(5))
        Console.WriteLine($"  Folder: {f.Name}");
}

// Check the Api project for references to understand the pattern
Console.WriteLine("\n=== API PROJECT REFERENCES (pattern check) ===");
var apiProjects = projects.Where(p => p.ProjectFile?.Contains("Api") == true && !p.ProjectFile.Contains(".sln"));
foreach (var proj in apiProjects.Take(1))
{
    var props = proj.FindChildrenRecursive<Property>()
        .Where(p => p.Name != null && p.Name.Contains("Reference"));
    foreach (var p in props.Take(10))
        Console.WriteLine($"  Property: {p.Name} = {p.Value?.Substring(0, Math.Min(100, p.Value?.Length ?? 0))}");
}
