using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Check resolved references for Services project - does Newtonsoft appear?
var messages = build.FindChildrenRecursive<Message>()
    .Where(m => m.Text != null && m.Text.Contains("Newtonsoft") && !m.Text.Contains("TaskRun"))
    .Take(20);
Console.WriteLine("=== NEWTONSOFT REFERENCES IN BUILD ===");
foreach (var m in messages)
    Console.WriteLine($"  {m.Text.Substring(0, Math.Min(300, m.Text.Length))}");

// Check the compiler command line for Services
Console.WriteLine("\n=== CSC COMMAND FOR SERVICES (reference section) ===");
var tasks = build.FindChildrenRecursive<Microsoft.Build.Logging.StructuredLogger.Task>()
    .Where(t => t.Name == "Csc");
foreach (var t in tasks)
{
    var proj = t.Parent;
    while (proj != null && !(proj is Project)) proj = proj.Parent as TreeNode;
    if (proj is Project p && p.ProjectFile?.Contains("Services") == true)
    {
        var cmdLine = t.FindChildrenRecursive<Message>()
            .Where(m => m.Text != null && m.Text.Contains("/reference:"))
            .Take(5);
        foreach (var m in cmdLine)
        {
            // Just check if Newtonsoft is referenced
            if (m.Text.Contains("Newtonsoft"))
                Console.WriteLine("  Newtonsoft IS in compiler references");
            else
                Console.WriteLine($"  Csc references (truncated): {m.Text.Substring(0, Math.Min(200, m.Text.Length))}...");
        }
        // Check CommandLineArguments
        var cla = t.FindChildrenRecursive<Property>()
            .Where(x => x.Name == "CommandLineArguments");
        foreach (var c in cla)
        {
            if (c.Value?.Contains("Newtonsoft") == true)
                Console.WriteLine("  Newtonsoft IS in CommandLineArguments");
            else
                Console.WriteLine("  Newtonsoft NOT in CommandLineArguments");
        }
        break;
    }
}

// Get the source lines from UserService.cs if available in messages
Console.WriteLine("\n=== ERROR CONTEXT ===");
var errors = build.FindChildrenRecursive<Error>();
foreach (var e in errors)
{
    Console.WriteLine($"  {e.File}:{e.LineNumber}:{e.ColumnNumber} [{e.Code}]");
    Console.WriteLine($"    {e.Text}");
}
