    if (proj is Project p && p.ProjectFile?.Contains("Services") == true)
    {
        var cmdLine = t.FindChildrenRecursive<Message>()
            .Where(m => m.Text != null && m.Text.Contains("/reference:"))
            .Take(5);
        foreach (var m in cmdLine)
        {
            // Just check if Newtonsoft is referenced
            if (m.Text.Contains("Newtonsoft"))
                Console.WriteLine("  Newtonsoft IS in compiler references");
            else
                Console.WriteLine($"  Csc references (truncated): {m.Text.Substring(0, Math.Min(200, m.Text.Length))}...");
        }
        // Check CommandLineArguments
        var cla = t.FindChildrenRecursive<Property>()
            .Where(x => x.Name == "CommandLineArguments");
        foreach (var c in cla)
        {
            if (c.Value?.Contains("Newtonsoft") == true)
                Console.WriteLine("  Newtonsoft IS in CommandLineArguments");
            else
                Console.WriteLine("  Newtonsoft NOT in CommandLineArguments");
        }
        break;
    }
}

